<template>
  <div class="container">
    <div class="legend">
      <el-checkbox-group v-model="checkedLegends" @change="handleLegendChange">
        <template v-for="(item, index) in top16Legend">
          <el-checkbox :key="index" :label="item">
            <span class="ric" :style="{ background: top16Colors[index] }"></span>{{ item }}
          </el-checkbox>
          <br :key="`br-${index}`" v-if="index > 0 && index % 4 === 0" />
        </template>
      </el-checkbox-group>
    </div>
    <div ref="LineChartShort" class="LineChartShort"></div>
  </div>
</template>

<script>
export default {
  name: 'LineChartShort',
  props: {
    chartData: {
      type: Array,
      default: () => [],
    },
    alarmTotal: {
      type: Number,
      default: 0,
    },
    colorStops: {
      type: Array,
      default: () => [],
    },
  },
  data() {
    return {
      chartInstance: null,
      /* 原始数据保持不动，仅用于计算 */
      rawLegendData: [
        'Human Experts',
        'Gemini-1.5-Pro-002',
        'Gemini-1.5-Flash-002',
        'Gemini-1.5-Flash-8B',
        'GPT-4o',
        'Qwen-VL-Max',
        'Qwen2.5-VL-72B',
        'Time-R1-7B',
        'Qwen2.5-VL-7B',
        'LLVA-Video-72B',
        'E.T. Chat-3.8B',
        'LongVU-7B',
        'MiniCPM v2.6-8B',
        'Time-R1-3B'
      ],

      rawSeriesData: [
        [90.74,88.89,91.87,90.32,89.25,93.37,90.53],
        [48.24,58.35,74.30,65.46,75.77,86.08,56.85],
        [41.41,52.24,69.51,55.41,68.30,81.85,48.41],
        [32.71,40.71,59.00,43.81,53.35,71.91,38.26],
        [24.32,38.41,63.97,28.64,43.95,69.75,26.48],
        [12.44,16.67,34.16,17.14,21.23,40.55,14.79],
        [8.86,16.82,35.95,13.58,27.41,51.35,11.22],
        [7.95,15.91,35.33,11.88,20.54,44.95,9.92],
        [5.39,7.49,21.25,8.28,13.45,29.55,6.83],
        [1.59,2.50,6.82,0.99,2.96,8.72,1.29],
        [0.76,1.76,4.25,1.62,3.50,6.27,1.19],
        [0.68,1.82,3.56,1.23,2.22,4.05,0.96],
        [0.23,0.68,4.79,0.74,2.22,6.48,0.49],
        [0.45, 1.36, 4.27, 0.74, 2.47, 5.81, 0.60]
      ],
      /* 仅保留 16 种颜色 */
      rawColors: [
        '#FF5F5F', '#9E7CFF', '#40C4FF', '#69F0AE',
        '#FFF153', '#FF764B', '#EE88FF', '#279BCF',
        '#9CCC65', '#AEE5FF', '#FFA8B3', '#FFD700',
        '#FF69B4', '#8A2BE2', '#FF4500', '#2E8B57'
      ],
      checkedLegends: [],
    };
  },
  computed: {
    /* 1. 按 Avg 降序取前 16 个模型 */
    sortedTop16() {
      return this.rawSeriesData
        .map((d, idx) => ({ idx, avg: d[6] }))
        .sort((a, b) => b.avg - a.avg)
        .slice(0, 16);
    },
    /* 2. 仅 16 种颜色，且与排序后顺序一一对应 */
    top16Colors() {
      const base16 = this.rawColors.slice(0, 16);
      return this.sortedTop16.map((_, i) => base16[i]);
    },
    top16Legend() {
      return this.sortedTop16.map(item => this.rawLegendData[item.idx]);
    },
    top16Series() {
      return this.sortedTop16.map(item => this.rawSeriesData[item.idx]);
    },
    /* 3. 构造 modelColors 映射（排序后模型名 -> 上面 16 色） */
    modelColors() {
      const map = {};
      this.top16Legend.forEach((name, i) => {
        map[name] = this.top16Colors[i];
      });
      return map;
    }
  },
  watch: {
    chartData: {
      deep: true,
      handler() {
        this.$nextTick(() => {
          this.updateChart();
        });
      },
    },
  },
  mounted() {
    this.initChart();
    this.checkedLegends = [...this.top16Legend];
    this.updateChart();
  },
  beforeDestroy() {
    if (this.chartInstance) {
      this.chartInstance.dispose();
      this.chartInstance = null;
    }
  },
  methods: {
    initChart() {
      this.chartInstance = this.$echarts.init(this.$refs.LineChartShort);
    },
    updateChart() {
      const option = this.chartOption();
      // 强制更新，避免缓存问题
      this.chartInstance.setOption(option, true);
    },
    chartOption() {
      const visibleSeries = this.top16Legend.reduce((acc, name) => {
        if (this.checkedLegends.includes(name)) {
          const dataIdx = this.top16Legend.indexOf(name);
          acc.push({
            name,
            type: 'bar',
            data: this.top16Series[dataIdx],
            color: this.modelColors[name],
            barWidth: 8,
            barGap: 0.1
          });
        }
        return acc;
      }, []);

      return {
        tooltip: {
          trigger: 'axis',
          axisPointer: {
            type: 'shadow',
          },
          textStyle: {
            lineHeight: 18
          },
        },
        legend: {
          show: false
        },
        grid: {
          left: '3%',
          right: '3%',
          bottom: '25px',
          top: '5%',
          containLabel: false
        },
        xAxis: [
          {
            type: 'category',
            data: [
              'Object Recall@1x, tIoU=0.7',
              'Object Recall@1x, tIoU=0.5',
              'Object Average mAP',
              'Scene Recall@1x, tIoU=0.7',
              'Scene Recall@1x, tIoU=0.5',
              'Scene Average mAP',
              'Avg Recall@1x, tIoU=0.7'
            ],
            axisLine: {
              show: false
            },
            axisTick: {
              show: false
            },
            axisLabel: {
              show: true,
              textStyle: {
                color: '#E0E0E0'
              },
              interval: 0
            }
          }
        ],
        yAxis: [
          {
            type: 'value',
            axisLabel: {
              formatter: '{value}'
            },
            axisTick: {
              show: false
            },
            axisLine: {
              show: false,
              lineStyle: {
                color: '#E0E0E0',
                width: 1,
                type: 'solid'
              }
            },
            splitLine: {
              lineStyle: {
                color: '#7A7A7A'
              }
            }
          }
        ],
        series: visibleSeries
      };
    },
    handleLegendChange() {
      this.updateChart();
    }
  }
};
</script>

