      return types[this.navIndex]
    },
    currentTask() {
      return this.exampleIndex === 0 ? 'Object' : 'Scene'
    },
    currentExample() {
      return this.examplesData[`Example${this.currentMontage}${this.currentTask}`]
    }
  },
  watch: {},
  created() {},
  mounted() {
    // 初始化时执行一次默认排序
    this.handleSortChange({
      prop: 'Avg',
      order: 'descending'
    });
  },
  methods: {
    setActive(index) {
      this.activeIndex = index;
      const sections = [
            'home',
            'whats-new',
            'overview',
            'leaderboards',
            'evaluation',
            'nemobench-examples',
            'contact'
        ];
        const sectionId = sections[index];
        const element = document.getElementById(sectionId);
        if (element) {
          const offset = 64; // 导航栏高度
          const elementPosition = element.getBoundingClientRect().top + window.pageYOffset;
          window.scrollTo({
            top: elementPosition - offset,
            behavior: 'smooth'
          });
        }
    },
    setActiveTabShort(index) {
      this.activeTabShort = index;
    },
    setActiveTabMedium(index) {
      this.activeTabMedium = index;
    },
    setActiveTabLong(index) {
      this.activeTabLong = index;
    },
    switchLanguage(lang) {
      this.activeLang = lang;
    },
    navActive(index) {
      this.navIndex = index;
    },
    exampleActive(index) {
      this.exampleIndex = index;
    },
    renderHeader(label) {
      return (h) => {
        return h('span', {
          domProps: {
            innerHTML: label
          }
        });
      };
    },
    // 表格排序 { column, prop, order }
    handleSortChange({ column, prop, order }) {
      console.log(column)
      console.log(prop)
      console.log(order)
      // 升序排序
      if (order === 'ascending') {
        this.tableDataLong.sort((a, b) => {
          if (typeof a[prop] === 'string' && typeof b[prop] === 'string') {
            return a[prop].localeCompare(b[prop]);
          }
          return a[prop] - b[prop];
        });
      } else if (order === 'descending') {
        this.tableDataLong.sort((a, b) => {
          if (typeof a[prop] === 'string' && typeof b[prop] === 'string') {
            return b[prop].localeCompare(a[prop]);
          }
          return b[prop] - a[prop];
        });
      }
    },
    formatNumber(row, column, cellValue) {
      // 处理可能的字符串类型和空值
      const value = parseFloat(cellValue || 0);
      return value.toFixed(2);
    }
  },
}
